import{_ as s,o as a,c as t,ai as i}from"./chunks/framework.DQi1ytmF.js";const k=JSON.parse('{"title":"Template obligations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/style/template-obligations.md","filePath":"guide/style/template-obligations.md"}'),n={name:"guide/style/template-obligations.md"};function o(r,e,h,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/style/template-obligations.md for this page in Markdown format</div><h1 id="template-obligations" tabindex="-1">Template obligations <a class="header-anchor" href="#template-obligations" aria-label="Permalink to &quot;Template obligations&quot;">​</a></h1><p>Tests and visual captures describe things that were observed. A component template describes something earlier: what the component promises to display and what actions it exposes. CraftTS can derive those promises directly from the dependency graph and record a human judgement about each one.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">craft-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --kind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --tsconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/demo/tsconfig.graph.json</span></span></code></pre></div><p>No test or browser report is required. The command reads each <code>craftComponent</code> template and derives two kinds of obligation.</p><h2 id="render-and-command" tabindex="-1">Render and command <a class="header-anchor" href="#render-and-command" aria-label="Permalink to &quot;Render and command&quot;">​</a></h2><p>A <strong>render</strong> obligation starts at a reactive binding in the template and follows the graph to the state, computed value, query, or property that produces it.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">total</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> div</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ifNode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(user.isAdmin, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> strong</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(total))]);</span></span></code></pre></div><p>This template promises to render <code>user.isAdmin</code> and <code>total</code>. Two occurrences of the same target are one promise, not two.</p><p>A <strong>command</strong> obligation starts at a handler on an interactive element and follows the call chain it triggers.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">users</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> button</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;remove&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">click</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">remove</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(id) }, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Remove&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>This template promises that the named button invokes <code>users.remove</code>. The element tag and its literal name are part of the promise, so moving the action to a different control asks for a new judgement.</p><p>Computed or dynamic accesses that cannot be addressed are printed as <code>template-obligation-unresolved</code> diagnostics. They are known extraction gaps; they are never silently treated as if the template made no promise.</p><p>The derived obligation keeps two presentation forms. Its <code>statement</code> is a canonical English sentence and remains available in the API, CLI and agency handoffs. The review application uses the accompanying structured statement parts to render that same promise in the selected language. Neither form is part of the attested evidence hash, so wording changes do not invalidate a decision.</p><h2 id="what-renewed-means" tabindex="-1">What <code>renewed</code> means <a class="header-anchor" href="#what-renewed-means" aria-label="Permalink to &quot;What \`renewed\` means&quot;">​</a></h2><p>Every obligation has two independent keys:</p><table tabindex="0"><thead><tr><th>key</th><th>meaning</th></tr></thead><tbody><tr><td>code fingerprint</td><td>the transitive code slice behind the bound or invoked target</td></tr><tr><td>evidence</td><td>the canonical shape of the promise: direction, element, name, target, and target kind</td></tr></tbody></table><p>When implementation code changes but the template still promises the same thing, the state is <code>renewed</code>. The previous judgement carries forward without asking a person to review it again. When the template binds or invokes a different target, the evidence changes and the state is <code>review</code>.</p><p>An attested obligation is <strong>not a passing test</strong>. It says that a person confirmed the promise was intentional. It does not prove that the implementation fulfils that promise at runtime.</p><h2 id="removing-a-promise-is-a-decision" tabindex="-1">Removing a promise is a decision <a class="header-anchor" href="#removing-a-promise-is-a-decision" aria-label="Permalink to &quot;Removing a promise is a decision&quot;">​</a></h2><p>If an attested template obligation disappears, <code>status --kind template</code> exits with a failure until the removal is signed. The ledger line is retained and marked with why the promise went away:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">craft-ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> retire</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --kind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --subject</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;template:component:src/card.ts:Card#command:property:src/card.ts:save&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --reason</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> superseded</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --note</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Saving is automatic now.&#39;</span></span></code></pre></div><p>The reasons are:</p><ul><li><code>superseded</code>: the product now fulfils the need another way;</li><li><code>defect</code>: the former promise was wrong;</li><li><code>derivation</code>: the extractor produced an obligation it should not have. Track this count as a quality signal for the extractor.</li></ul><p>The note is mandatory because absence is otherwise indistinguishable from an accidental deletion. If a retired obligation later reappears, it returns to the review queue; the next human verdict clears the retirement.</p><h2 id="measured-rename-noise" tabindex="-1">Measured rename noise <a class="header-anchor" href="#measured-rename-noise" aria-label="Permalink to &quot;Measured rename noise&quot;">​</a></h2><p>The target identity remains part of the evidence because the implementation measurement stayed inside its review budget. Replaying the latest 20 commits that touched <code>apps/demo</code> produced a median of <strong>0 actionable obligation changes per commit</strong> (one commit removed four obligations, one added three, and the other eighteen changed none), with <strong>0 changes attributable to a pure target rename</strong>. This is below the threshold of three, so mass renames can continue to be handled by review clustering without weakening the promise recorded in the evidence.</p>`,27)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
